def f(I):
    I=np.array(I); H,W=I.shape
    # background = most common; noise = 5; specials = rest
    cnt={}
    for v in set(I.flatten()): cnt[v]=cnt.get(v,0)+1
    bg=max(cnt,key=lambda v:cnt[v])
    O=np.zeros((H//3,W//3),dtype=int)
    for v in sorted(set(np.unique(I.tolist()))-{bg,5}):
        for c in comps(I,v):
            ys=[p[0] for p in c]; xs=[p[1] for p in c]
            O[min(ys)//3][min(xs)//3]=v
    return O.tolist()
